'use strict';
const test=require('node:test');const assert=require('node:assert/strict');
const {coord,buildUrl,extract,createRouteCache,resolveRoutes}=require('./routing');
const o={lat:43.3,lon:5.4},a={id:'A',lat:43.31,lon:5.41},b={id:'B',lat:43.32,lon:5.42};
function fake(){const urls=[];const fetchFn=async url=>{urls.push(url);let inbound=url.includes('destinations=0');return {ok:true,json:async()=>({code:'Ok',distances:inbound?[[1100],[3200]]:[[1000,3000]]})};};return {fetchFn,urls};}
test('coords longitude,latitude',()=>assert.equal(coord(o),'5.4,43.3'));
test('reject invalid latitude',()=>assert.throws(()=>coord({lat:100,lon:0})));
test('reject invalid longitude',()=>assert.throws(()=>coord({lat:0,lon:200})));
test('reject NaN',()=>assert.throws(()=>coord({lat:NaN,lon:1})));
test('outbound URL indexes',()=>assert.match(buildUrl('https://example.org/table/',o,[a,b],true),/sources=0&destinations=1;2/));
test('inbound URL indexes',()=>assert.match(buildUrl('https://example.org/table/',o,[a,b],false),/sources=1;2&destinations=0/));
test('reject HTTP base',()=>assert.throws(()=>buildUrl('http://x',o,[a],true)));
test('parse outward',()=>assert.deepEqual(extract({code:'Ok',distances:[[1,2]]},2,true),[1,2]));
test('parse inward',()=>assert.deepEqual(extract({code:'Ok',distances:[[1],[2]]},2,false),[1,2]));
test('reject bad matrix shape',()=>assert.throws(()=>extract({code:'Ok',distances:[[1,2]]},2,false)));
test('null route preserved',()=>assert.deepEqual(extract({code:'Ok',distances:[[null]]},1,true),[null]));
test('reject negative distance',()=>assert.deepEqual(extract({code:'Ok',distances:[[-1]]},1,true),[null]));
test('asymmetric roundtrip',async()=>{const f=fake();const r=await resolveRoutes({origin:o,stations:[a,b],fetchFn:f.fetchFn});assert.equal(r[0].distanceRoundTripKm,2.1);assert.equal(r[1].distanceRoundTripKm,6.2);assert.equal(f.urls.length,2);});
test('cache avoids requests',async()=>{const f=fake(),cache=createRouteCache();await resolveRoutes({origin:o,stations:[a,b],fetchFn:f.fetchFn,cache,now:()=>100});const r=await resolveRoutes({origin:o,stations:[a,b],fetchFn:f.fetchFn,cache,now:()=>101});assert.equal(f.urls.length,2);assert.ok(r.every(x=>x.fromCache));});
test('cache expiry triggers requests',async()=>{const f=fake(),cache=createRouteCache();await resolveRoutes({origin:o,stations:[a,b],fetchFn:f.fetchFn,cache,ttlMs:5,now:()=>100});await resolveRoutes({origin:o,stations:[a,b],fetchFn:f.fetchFn,cache,ttlMs:5,now:()=>106});assert.equal(f.urls.length,4);});
test('changed origin invalidates cache',async()=>{const f=fake(),cache=createRouteCache();await resolveRoutes({origin:o,stations:[a,b],fetchFn:f.fetchFn,cache});await resolveRoutes({origin:{lat:43.301,lon:5.4},stations:[a,b],fetchFn:f.fetchFn,cache});assert.equal(f.urls.length,4);});
test('changed station coordinates invalidates cache',async()=>{let calls=0;const cache=createRouteCache(),fetchFn=async()=>{calls++;return {ok:true,json:async()=>({code:'Ok',distances:[[1000]]})}};await resolveRoutes({origin:o,stations:[a],fetchFn,cache});await resolveRoutes({origin:o,stations:[{...a,lat:43.311}],fetchFn,cache});assert.equal(calls,4);});
test('HTTP failure marks unavailable',async()=>{const r=await resolveRoutes({origin:o,stations:[a],fetchFn:async()=>({ok:false})});assert.equal(r[0].distanceRoundTripKm,null);});
test('network failure marks unavailable',async()=>{const r=await resolveRoutes({origin:o,stations:[a],fetchFn:async()=>{throw Error('offline')}});assert.equal(r[0].status,'route_unavailable');});
test('null return leg marks unavailable',async()=>{let n=0;const r=await resolveRoutes({origin:o,stations:[a],fetchFn:async()=>({ok:true,json:async()=>({code:'Ok',distances:++n===1?[[2000]]:[[null]]})})});assert.equal(r[0].distanceRoundTripKm,null);});
test('empty station list no request',async()=>{let n=0;assert.deepEqual(await resolveRoutes({origin:o,stations:[],fetchFn:async()=>{n++}}),[]);assert.equal(n,0);});
test('duplicate id rejected',async()=>await assert.rejects(resolveRoutes({origin:o,stations:[a,a],fetchFn:async()=>{}})));
test('batchSize upper bound',async()=>await assert.rejects(resolveRoutes({origin:o,stations:[],fetchFn:async()=>{},batchSize:26})));
test('batching 3 stations with size 2',async()=>{let calls=0;const r=await resolveRoutes({origin:o,stations:[a,b,{id:'C',lat:43.33,lon:5.43}],batchSize:2,fetchFn:async url=>{calls++;const count=url.includes('1;2')?2:1;const inbound=url.includes('destinations=0');return {ok:true,json:async()=>({code:'Ok',distances:inbound?Array.from({length:count},()=>[1000]):[Array.from({length:count},()=>1000)]})}}});assert.equal(calls,4);assert.equal(r.length,3);});
test('invalid OSRM code marks unavailable',async()=>{const r=await resolveRoutes({origin:o,stations:[a],fetchFn:async()=>({ok:true,json:async()=>({code:'NoRoute'})})});assert.equal(r[0].status,'route_unavailable');});
test('abort stops processing',async()=>{const controller=new AbortController();controller.abort();await assert.rejects(resolveRoutes({origin:o,stations:[a],fetchFn:async()=>{},signal:controller.signal}),/annulé/);});
test('no mutation of stations',async()=>{const s=Object.freeze({...a});await resolveRoutes({origin:o,stations:[s],fetchFn:async()=>({ok:false})});assert.deepEqual(s,a);});
